import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { writeFileSync,mkdirSync } from "node:fs";
import { join } from "node:path";
import Database from "better-sqlite3";
import { canonicalDigest } from "../../src/domain/request-digest";
import { boundedLaunch,boundedBrowser,boundedFetch,readBoundedText,boundedProxy } from "./w01-runtime";
import { invokeCli } from "./w01-legacy-performance";
import { captureEventSpool,capturePendingSpool,validateEventSpool } from "./w01-spool";
import { pairPage } from "./p03";
import { copySeed,type W02Prepared } from "./w02-preparation";
import { browserRequest,dispatchCurrent,summarizeCurrent,teardownAll,type CurrentExpected,type VisibilityReceipt } from "./w02-measurement";
import type { TaskSnapshot } from "../../src/contracts/tasks";
export type { VisibilityReceipt } from "./w02-measurement";
export async function currentScenario(p:W02Prepared,scenario:number,root:string,receipt:VisibilityReceipt,save:()=>void,transitions=10,enforceBudget=true){
 const dir=copySeed(p,"scenario",join(root,"visibility-"+scenario)),server=await boundedLaunch({dir,cwd:p.sources.head}),resources=[{name:"service",close:server.stop}];let primary:unknown;
 try{const ownedBrowser=await boundedBrowser();resources.unshift({name:"browser",close:ownedBrowser.close});const contexts=await Promise.all([ownedBrowser.browser.newContext({viewport:{width:1440,height:1100}}),ownedBrowser.browser.newContext({viewport:{width:1440,height:1100}})]),pages=await Promise.all(contexts.map(c=>c.newPage()));for(const page of pages)await pairPage(page,server);
 const seed=p.seeds.head,taskId=p.diamond[3],prerequisiteId=p.diamond[1];
 const browserCommand=(path:string,input:unknown,method="POST",key=randomUUID())=>browserRequest(pages[0],path,input,method,key,receipt.originals,save);
 const current=async(id:string)=>{const response=await boundedFetch(server.url+"/api/v1/tasks/"+id,{headers:{Authorization:"Bearer "+server.credentials().reporterToken}});return JSON.parse(await readBoundedText(response)).data as {task:TaskSnapshot;evidence:TaskSnapshot["evidence"];readiness:TaskSnapshot["readiness"]};};
 let t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/dependencies`,{expectedVersion:t.version,prerequisiteIds:scenario===1?[prerequisiteId]:[]},"PUT");
 t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/review-policy`,{expectedVersion:t.version,reviewRequired:scenario!==1,verificationRequired:false},"PATCH");
 const token=join(dir,"cli-token"),outbox=join(root,"visibility-outbox-"+scenario);writeFileSync(token,server.credentials().reporterToken,{mode:0o600});mkdirSync(outbox,{mode:0o700});let paused=false;const proxy=await boundedProxy(server,(request,body,reply)=>{if(request.url?.endsWith("/events")){const input=JSON.parse(body.toString());if(!reply){receipt.originals.push({kind:"spool",input,capture:captureEventSpool(outbox,{kind:"run",id:input.runId},input)});if(paused){const response={status:503,body:JSON.stringify({error:{code:"synthetic_queue_control",message:"Synthetic queue before measurement"}})};receipt.originals.push({kind:"syntheticOutage",input,...response});save();return response;}}else receipt.originals.push({kind:"eventACK",input,status:reply.status,text:reply.body.toString(),generation:reply.generation});save();}});resources.unshift({name:"proxy",close:proxy.close});const env={PORT:String(proxy.port),AGENTFLOW_REPORTER_TOKEN_FILE:token,AGENTFLOW_OUTBOX_DIR:outbox};let count=0;const file=(input:unknown)=>{const path=join(dir,`visibility-input-${count++}.json`);writeFileSync(path,JSON.stringify(input),{mode:0o600});return path;};
 const cli=async(args:string[])=>{const result=await invokeCli(p.sources.head,args,env);receipt.originals.push({kind:"cli",args,...result});save();assert.equal(result.code,0,result.stderr);return JSON.parse(result.stdout);};
 const register=async(purpose:string,id:string,task:TaskSnapshot)=>{await cli(["run","register","--file",file({id,projectId:seed.projectId,taskId:task.id,agentId:seed.agents[0],purpose,expectedTaskVersion:task.version,...(purpose==="review"?{workRevision:task.workRevision,artifactRef:"synthetic:same",reworkRound:task.reworkRound}:{})}),"--idempotency-key",randomUUID()]);await cli(["report","--run",id,"--type","run.started","--payload",file({})]);};
 const implement=async()=>{const id=randomUUID();await register("implementation",id,(await current(taskId)).task);await cli(["report","--run",id,"--type","run.succeeded","--payload",file({summary:"Synthetic new work",artifactRef:"synthetic:same"})]);};
 if(scenario!==1)await implement();
 if(scenario===1){const prereq=(await current(prerequisiteId)).task;await browserCommand(`/tasks/${prerequisiteId}/dependencies`,{expectedVersion:prereq.version,prerequisiteIds:[]},"PUT");}
 const nodeId=p.workflow.nodeIds[23],url=server.url+`/projects/${seed.projectId}/workflows?workflowId=${p.workflow.workflowId}&revisionId=${p.workflow.revisionId}&nodeId=${nodeId}`;for(let context=0;context<2;context++){await pages[context].goto(url+(context===1?"&view=list":""));await pages[context].locator(`.acceptance-facts[data-task-id="${taskId}"] [data-current-fact="${scenario===1?"readiness":"review"}"]`).scrollIntoViewIfNeeded();}
 for(let index=0;index<transitions;index++){let origin:string,eventId="",decision="none",ready=true,expectedVersion:number;let dispatch:()=>Promise<unknown>;
  if(scenario===1){let prerequisite=(await current(prerequisiteId)).task;const accepting=index%2===0;if(accepting){await browserCommand(`/tasks/${prerequisiteId}`,{expectedVersion:prerequisite.version,status:"review"},"PATCH");prerequisite=(await current(prerequisiteId)).task;}const key=randomUUID(),path=`/tasks/${prerequisiteId}/${accepting?"complete":"reopen"}`,input=accepting?{expectedVersion:prerequisite.version,evidenceNote:"Synthetic measured prerequisite acceptance"}:{expectedVersion:prerequisite.version,reason:"Synthetic measured prerequisite reopen"};origin="command:"+key;ready=accepting;t=(await current(taskId)).task;expectedVersion=t.version;dispatch=()=>browserCommand(path,input,"POST",key);
  }else if(scenario===3&&index%2===0){t=(await current(taskId)).task;const key=randomUUID();origin="command:"+key;expectedVersion=t.version+1;dispatch=()=>browserCommand(`/tasks/${taskId}/rework`,{expectedVersion:t.version,reason:"Synthetic measured same-reference rework"},"POST",key);t={...t,workRevision:t.workRevision+1,reworkRound:t.reworkRound+1};
  }else{if(scenario===3)await implement();else{t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/artifact`,{expectedVersion:t.version,artifactRef:"synthetic:transition-"+index},"POST");
  }t=(await current(taskId)).task;const detail=await current(taskId),ref=detail.evidence.currentArtifact!.artifactRef,id=randomUUID();await cli(["run","register","--file",file({id,projectId:seed.projectId,taskId,agentId:seed.agents[0],purpose:"review",expectedTaskVersion:t.version,workRevision:t.workRevision,artifactRef:ref,reworkRound:t.reworkRound}),"--idempotency-key",randomUUID()]);await cli(["report","--run",id,"--type","run.started","--payload",file({})]);decision=scenario===2&&index%2?"changes_requested":"approved";paused=true;const queued=await invokeCli(p.sources.head,["report","--run",id,"--type","run.succeeded","--payload",file({summary:"Synthetic measured gate",decision,evidenceNote:"Synthetic transition"})],env);receipt.originals.push({kind:"queuedCLI",...queued});assert.equal(queued.code,2,queued.stderr);const pending=capturePendingSpool(outbox,{kind:"run",id});assert.equal(pending.length,1);validateEventSpool(pending[0],pending[0].body);eventId=String(pending[0].body!.eventId);origin="event:"+eventId;t=(await current(taskId)).task;expectedVersion=t.version;paused=false;dispatch=()=>cli(["flush","--run",id]);}
  const artifactRef=scenario===3&&index%2===0?"":(await current(taskId)).evidence.currentArtifact?.artifactRef??"";const expected=pages.map((_,context)=>({projectId:seed.projectId,workflowId:p.workflow.workflowId,revisionId:p.workflow.revisionId,nodeId,scenario,index,context,fact:scenario===1?"readiness" as const:"review" as const,view:context===0?"graph" as const:"list" as const,origin,taskId,version:expectedVersion,workRevision:t.workRevision,reworkRound:t.reworkRound,artifactRef,ready,decision,eventId}));await dispatchCurrent(receipt,expected,pages,dispatch,save,5000,enforceBudget);}
 }catch(error){primary=error;}finally{await teardownAll(primary,resources,receipt.failures);}
 const db=new Database(join(dir,"agentflow.sqlite"),{readonly:true});try{for(const original of receipt.originals){const o=original as {kind:string;path:string;method:string;key:string;input:unknown;text:string;status:number};if(o.kind==="browser"){const row=db.prepare("SELECT * FROM receipts WHERE key=? AND path=? AND method=?").get(o.key,"/api/v1"+o.path,o.method) as {digest:string;body:string;status:number};assert(row);assert.equal(row.digest,canonicalDigest(o.input));assert.equal(row.status,o.status);assert.deepEqual(JSON.parse(row.body),JSON.parse(o.text));}if(o.kind==="eventACK"){const input=o.input as {eventId:string},row=db.prepare("SELECT * FROM run_events WHERE event_id=?").get(input.eventId) as {digest:string;acknowledgement:string};assert(row);assert.equal(row.digest,canonicalDigest(o.input));assert.deepEqual(JSON.parse(row.acknowledgement),JSON.parse(o.text));}}for(const e of receipt.expected.filter(e=>e.context===0&&e.eventId)){const row=db.prepare("SELECT * FROM gate_decisions WHERE event_id=?").get(e.eventId) as {task_id:string;work_revision:number;rework_round:number;artifact_ref:string;decision:string};assert(row);assert.equal(row.task_id,e.taskId);assert.equal(row.work_revision,e.workRevision);assert.equal(row.rework_round,e.reworkRound);assert.equal(row.artifact_ref,e.artifactRef);assert.equal(row.decision,e.decision);}assert.deepEqual(db.pragma("foreign_key_check"),[]);receipt.rows=[...db.prepare("SELECT * FROM gate_decisions").all(),...db.prepare("SELECT * FROM receipts").all(),...db.prepare("SELECT * FROM run_events").all()];save();}finally{db.close();}receipt.summary=summarizeCurrent(receipt.expected,receipt.captures);save();return receipt.summary;
}
